<script lang="ts">
  import { onMount } from 'svelte'; import Navbar from './lib/components/Navbar.svelte'; import VocabTab from './lib/tabs/VocabTab.svelte'; import DictionaryTab from './lib/tabs/DictionaryTab.svelte'; import GrammarTab from './lib/tabs/GrammarTab.svelte'; import DictationTab from './lib/tabs/DictationTab.svelte'; import ListeningTab from './lib/tabs/ListeningTab.svelte'; import WritingTab from './lib/tabs/WritingTab.svelte'; import ObsidianTab from './lib/tabs/ObsidianTab.svelte'; import SettingsTab from './lib/tabs/SettingsTab.svelte'; import { GetWordCount, GetDailyVocab, GetDailyIdiom } from '../wailsjs/go/main/App.js'; import { getInitialThemeState, applyThemeState, type ColorMode, type ThemePalette } from './lib/utils/theme';
  type Area = 'today'|'dictionary'|'learn'|'practice'|'library'|'settings'; const defaults: Record<Area,string>={today:'today',dictionary:'dictionary',learn:'vocab',practice:'dictation',library:'obsidian',settings:'settings'}; const subnav: Partial<Record<Area,{id:string;label:string}[]>>={learn:[{id:'vocab',label:'Vocabulary'}],practice:[{id:'dictation',label:'Dictation'},{id:'listening',label:'Listening'},{id:'grammar',label:'Grammar'},{id:'writing',label:'Writing Lab'}],library:[{id:'obsidian',label:'Saved & Obsidian'}]};
  let activeArea=$state<Area>('today'); let currentView=$state('today'); let dictionaryInitialWord=$state('serendipity'); let palette=$state<ThemePalette>('default'); let colorMode=$state<ColorMode>('dark'); let dictionaryWordCount=$state<number|null>(null); let dueCount=$state(0); let idiom=$state<any>(null);
  async function refreshDictionaryWordCount(){try{dictionaryWordCount=await GetWordCount()}catch(e){console.warn(e)}}
  function selectArea(area:string){activeArea=area as Area;currentView=defaults[activeArea]}; function selectView(view:string){currentView=view}; function dictionary(word:string){dictionaryInitialWord=word;activeArea='dictionary';currentView='dictionary'}; function toggleMode(){colorMode=colorMode==='dark'?'light':'dark';applyThemeState({palette,colorMode})}
  onMount(async()=>{const initial=getInitialThemeState();palette=initial.palette;colorMode=initial.colorMode;applyThemeState(initial);refreshDictionaryWordCount();try{const [due,dailyIdiom]=await Promise.all([GetDailyVocab('due_srs',5),GetDailyIdiom()]);dueCount=(due||[]).length;idiom=dailyIdiom}catch(e){console.warn(e)}});
</script>
<div class="min-h-screen flex flex-col app-container transition-colors duration-200"><Navbar {activeArea} {colorMode} onSelectArea={selectArea} onToggleColorMode={toggleMode}/>{#if subnav[activeArea]}<div class="border-b border-slate-800/70"><div class="px-4 sm:px-6 lg:px-8 flex gap-1 overflow-x-auto">{#each subnav[activeArea]||[] as item}<button onclick={()=>selectView(item.id)} class={`px-3 py-2.5 text-sm border-b-2 cursor-pointer ${currentView===item.id?'border-cyan-400 text-cyan-300':'border-transparent text-slate-500 hover:text-slate-300'}`}>{item.label}</button>{/each}</div></div>{/if}<main class="flex-1 w-full p-4 sm:p-6 lg:p-8 2xl:px-12">{#if currentView==='today'}<div class="w-full max-w-6xl mx-auto space-y-5"><section class="rounded-2xl border border-slate-800 bg-slate-900/60 p-6 sm:p-8"><p class="text-sm font-medium text-cyan-300">Your daily English practice</p><h2 class="mt-2 text-3xl font-semibold text-slate-100">Make progress in 20 minutes.</h2><p class="mt-2 text-slate-400">Review what is due, learn a few useful words, then practise with one focused lesson.</p><button onclick={()=>selectArea('learn')} class="mt-6 px-5 py-3 rounded-xl bg-cyan-500 text-slate-950 font-semibold cursor-pointer">Continue learning</button></section><div class="grid lg:grid-cols-3 gap-4"><button onclick={()=>selectArea('learn')} class="text-left rounded-xl border border-slate-800 bg-slate-900/50 p-5 cursor-pointer"><p class="text-xs text-cyan-300">4 min</p><h3 class="mt-4 font-semibold text-slate-100">Review due words</h3><p class="mt-1 text-sm text-slate-400">{dueCount} words ready</p></button><button onclick={()=>selectArea('practice')} class="text-left rounded-xl border border-slate-800 bg-slate-900/50 p-5 cursor-pointer"><p class="text-xs text-cyan-300">6 min</p><h3 class="mt-4 font-semibold text-slate-100">Practise dictation</h3><p class="mt-1 text-sm text-slate-400">Train your ear with one sentence.</p></button><button onclick={()=>{activeArea='practice';currentView='listening'}} class="text-left rounded-xl border border-slate-800 bg-slate-900/50 p-5 cursor-pointer"><p class="text-xs text-cyan-300">8 min</p><h3 class="mt-4 font-semibold text-slate-100">Listen and repeat</h3><p class="mt-1 text-sm text-slate-400">Short dialogue, exact transcript.</p></button></div>{#if idiom}<section class="rounded-xl border border-slate-800 bg-slate-900/50 p-5"><p class="text-xs uppercase text-indigo-300">Daily idiom</p><h3 class="mt-2 text-xl font-semibold text-slate-100">{idiom.idiom}</h3><p class="mt-2 text-slate-300">{idiom.meaning_en}</p></section>{/if}</div>{:else if currentView==='vocab'}<VocabTab onNavigateToDictionary={dictionary}/>{:else if currentView==='dictionary'}<DictionaryTab initialWord={dictionaryInitialWord} wordCount={dictionaryWordCount} onWordStored={refreshDictionaryWordCount}/>{:else if currentView==='dictation'}<DictationTab/>{:else if currentView==='listening'}<ListeningTab/>{:else if currentView==='grammar'}<GrammarTab/>{:else if currentView==='writing'}<WritingTab onNavigateTab={selectView}/>{:else if currentView==='obsidian'}<ObsidianTab onNavigateToDictionary={dictionary}/>{:else if currentView==='settings'}<SettingsTab/>{/if}</main></div>
